    minOne = None
    minIndex = None
    for i in range(len(arr)):
        if i == blocked:
            continue
        else:
            curr_num = arr[i]
            if minOne == None or curr_num < minOne:
                minOne = curr_num
                minIndex = i
    minTwo = None
    minIndexTwo = None
    for j in range(len(arr)):
