def build1(s):
    s = s.replace(' ', '')
    stack = []
    s += '!'
    if s[0] == '-':
        s = '0' + s
    j = 0
    for i in range(len(s)):
        if s[i] in ['+', '-', '*', '/', '(', ')', '!']:
            if j < i:
                stack.append(s[j:i])
            stack.append(s[i])
            j = i + 1
    stack.remove('!')
    for (i, x) in enumerate(stack):
        if x not in ['+', '-', '*', '/', '(', ')', '!']:
