def build2(s):
    while ')' in s:
        end = s.index(')')
        start = end
        while s[start] != '(':
            start -= 1
        s = s[:start] + [build2(s[start + 1:end])] + s[end + 1:]
    op = {'+': lambda x, y: x + y, '-': lambda x, y: x - y, '*': lambda x, y: x * y, '/': lambda x, y: x.__div__(y)}
    i = 2
    for order in [0, 1]:
        i = 2
        while i < len(s):
            if order == 0 and s[i - 1] in ['*', '/'] or (order == 1 and s[i - 1] in ['+', '-']):
                s[i - 2] = op[s[i - 1]](s[i - 2], s[i])
                s.pop(i)
                s.pop(i - 1)
            else:
                i += 2
    return s[0]

