def checktree(preorder, inorder, postorder, N):
    flag = [False]

    def rec1(a, b):
        if flag[0]:
            return None
        if not a:
            return None
        ele = b.pop(0)
        if ele not in a:
            flag[0] = True
            return None
        ind = a.index(ele)
        node = Tree(ele)
        node.left = rec1(a[:ind], b)
        node.right = rec1(a[ind + 1:], b)
        return node

    def rec2(a, b):
        if flag[0]:
            return None
        if not a:
            return None
        ele = b.pop(0)
        if ele not in a:
            flag[0] = True
            return None
        ind = a.index(ele)
        node = Tree(ele)
        node.right = rec2(a[ind + 1:], b)
        node.left = rec2(a[:ind], b)
        return node
    root1 = rec1(inorder, preorder)
    root2 = rec2(inorder, postorder[::-1])

    def identicalTrees(a, b):
        if a is None and b is None:
            return True
        if a is not None and b is not None:
            return a.data == b.data and identicalTrees(a.left, b.left) and identicalTrees(a.right, b.right)
        return False
    if identicalTrees(root1, root2) and (not flag[0]):
        return True
    return False

