    self.dfs(counter, [])
    return self.result

def dfs(counter, curr):
    if curr:
        self.result += 1
    for x in counter:
        curr1 = curr.copy()
        counter1 = counter.copy()
        curr1.append(x)
        counter1[x] -= 1
        if counter1[x] == 0:
            del counter1[x]
        self.dfs(counter1, curr1)

def numtilepossibilities(s: str) -> int:
    (ans, C) = (0, Counter(s))

    def dfs(C, cur):
        nonlocal ans
        if cur:
            ans += 1
        if not C:
            return
        C1 = C.copy()
        for x in C:
            cur.append(x)
            C1[x] -= 1
            if C1[x] == 0:
                del C1[x]
            dfs(C1, cur)
            cur.pop()
            C1[x] += 1
    dfs(C, cur=[])
    return ans

def numtilepossibilities(tiles: str) -> int:
    tiles = ''.join(sorted(tiles))
    uniques = self.step(tiles)
    return len(uniques) - 1

def step(tiles: str) -> set:
    if len(tiles) == 0:
        return {''}
    if tiles not in self.memos:
        uniques = set()
        for i in range(len(tiles)):
            c = tiles[i]
            substr = tiles[:i] + tiles[i + 1:]
            substrs_set = self.step(substr)
            for substr in substrs_set:
                uniques.add(substr)
                for j in range(len(substr) + 1):
                    new_str = substr[:j] + c + substr[j:]
                    uniques.add(new_str)
        self.memos[tiles] = uniques
    return self.memos[tiles]

def numtilepossibilities(tiles: str) -> int:
    res = set()

    def seq(s, l):
        if len(l) == 0:
            res.add(s)
            return
        seq(s, l[1:])
        for i in range(len(l)):
            seq(s + l[i], l[:i] + l[i + 1:])
    seq('', list(tiles))
    return len(res) - 1

