def sieve_for_seg(n):
    prime = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if prime[p] == True:
            for i in range(p * p, n + 1, p):
                prime[i] = False
        p += 1
    req = []
    for i in range(2, n + 1):
        if prime[i] == True:
            req.append(i)
    return req

def segmented_sieve(low, high):
    if low <= 2:
        return self.sieve_for_seg(high)
    else:
        limit = math.floor(math.sqrt(high)) + 1
        prime = self.sieve_for_seg(limit)
        n = high - low + 1
        mark = [True] * (n + 1)
        for p in prime:
            low_map = math.ceil(low / p) * p
            if low_map == p:
                low_map += p
            for j in range(low_map, high + 1, p):
                mark[j - low] = False
        result = []
        for i in range(low, high + 1):
            if mark[i - low] == True:
                result.append(i)
        return result

