def perfectsum(arr, n, sum):
    m = 1000000007
    t = [[0 for I in range(sum + 1)] for _ in range(n + 1)]
    t[0][0] = 1
    for i in range(1, n + 1):
        for j in range(sum + 1):
            if arr[i - 1] <= j:
                t[i][j] = (t[i - 1][j - arr[i - 1]] + t[i - 1][j]) % m
            else:
                t[i][j] = t[i - 1][j] % m
    return t[n][sum] % m

