def __init__(maxsize):
    self.maxsize = maxsize
    self.top = -1
    self.arr = []

def empty():
    return self.top == -1

def full():
    return self.top == self.maxsize

def push(data):
    if self.full():
        return 'Stack is full'
    self.top += 1
    self.arr.append(data)

def peek():
    if self.empty():
        return 'Stack is empty'
    return self.arr[self.top]

def pop():
    if self.empty():
        return 'Stack is empty'
    top_ele = self.arr.pop()
    self.top -= 1
    return top_ele

