    sorted_chars = iter(sorted((c for c in s if c in sortable), key=str.lower))
    return ''.join((next(sorted_chars) if c in sortable else c for c in s))

def sort_string(s):
    it = iter(sorted([(i, x) for (i, x) in enumerate(s) if x.isalpha()], key=lambda p: (p[1].lower(), p[0])))
    return ''.join((next(it)[1] if x.isalpha() else x for x in s))

def sort_string(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    rule12 = list(sorted([x for x in s if x.lower() in alphabet], key=lambda i: alphabet.find(i.lower())))
    for (i, sym) in enumerate(s):
        if sym.lower() not in alphabet:
            rule12.insert(i, sym)
    return ''.join(rule12)

