def getPossiblePath(hash, index, d, dp):
    if index == d:
        return 1
    if dp[index] != -1:
        return dp[index]
    if index in hash:
        list = hash[index]
        result = 0
        for i in list:
            result += self.getPossiblePath(hash, i, d, dp)
        dp[index] = result
        return dp[index]
    else:
        return 0

