def merge(root, left, right):
    replace_left = replace_right = None
    for i in range(len(left)):
        if left[i] == root.left:
            replace_left = i
    for i in range(len(right)):
        if right[i] == root.right:
            replace_right = i
    if replace_left is not None and replace_right is None:
        left[replace_left] = root
        return left + right
    elif replace_right is not None and replace_left is None:
        right[replace_right] = root
        return left + right
    result = [node for node in left if node != root.left] + [node for node in right if node != root.right]
    result.append(root)
    return result

def helper(root, to_delete):
    if not root:
        return []
    if not root.left and (not root.right):
        if root.val in to_delete:
