    self.bfs(root, deleted, out)
    return out

def bfs(root, deleted, out):
    q = Queue()
    q.put((root, True))
    while q.qsize() > 0:
        (node, parent_delete) = q.get()
        if node.val in deleted:
            curr_delete = True
        else:
            curr_delete = False
        if node.left:
            q.put((node.left, curr_delete))
            if node.left.val in deleted:
                node.left = None
        if node.right:
            q.put((node.right, curr_delete))
            if node.right.val in deleted:
                node.right = None
        if curr_delete:
            node.left = None
            node.right = None
        elif parent_delete:
            out.append(node)

def delNodes(root: TreeNode, to_delete: List[int]) -> List[TreeNode]:
    roots = []
    roots.append(root)

    def removeRoot(root, roots):
        index = 0
        for i in roots:
            if i == root:
                roots.pop(index)
            index += 1

    def delete(root, prev, roots, to_delete):
        left = root.left
        right = root.right
        if root.val in to_delete:
            removeRoot(root, roots)
            if left:
                roots.append(root.left)
            if right:
                roots.append(root.right)
            root.left = None
            root.right = None
            if prev:
                if prev.left == root:
                    prev.left = None
                if prev.right == root:
                    prev.right = None
        if left:
            delete(left, root, roots, to_delete)
        if right:
            delete(right, root, roots, to_delete)
    delete(root, None, roots, to_delete)
    return roots

