    if k > 1:
        s += s
        n *= 2
    ans = 0
    i = 0
    while i < n:
        x = 0
        while i < n and s[i] == '0':
            (x, i) = (x + 1, i + 1)
        ans = max(ans, x)
        i += 1
    if k == 1 or ans != n:
        return ans
    else:
        return ans // 2 * k

def lcsk(k, st):
    n = len(st)
    dp = [0] * (n + 1)
    if st[0] == '0':
        dp[0] = 1
    for i in range(1, n):
        if st[i] == '0':
            dp[i] = dp[i - 1] + 1
        else:
            dp[i] = 0
    if dp[n - 1] == n:
        return n * k
    u = 0
    for i in range(n):
        if st[i] == '1':
            u = i - 1
            break
    if u == -1:
        return max(dp)
    else:
        return max(max(dp), dp[n - 1] + dp[u])

