def dfs(board, count):
    if count >= self.res:
        return
    (i, j) = self.find_next(board)
    if i == -1 and j == -1:
        self.res = min(self.res, count)
        return
    max_length = self.find_max_length(board, i, j)
    for k in range(1, max_length + 1)[::-1]:
        self.assign(board, i, j, k, 1)
        self.dfs(board, count + 1)
        self.assign(board, i, j, k, 0)

def assign(board, i, j, length, val):
    for row in range(i, i + length):
        for col in range(j, j + length):
            board[row][col] = val

def find_max_length(board, i, j):
    max_length = 1
    while i + max_length - 1 < self.m and j + max_length - 1 < self.n:
        for row in range(i, i + max_length):
            if board[row][j + max_length - 1] != 0:
                return max_length - 1
        for col in range(j, j + max_length):
            if board[i + max_length - 1][col] != 0:
                return max_length - 1
        max_length += 1
    return max_length - 1

def find_next(board):
    for i in range(self.m):
        for j in range(self.n):
            if board[i][j] == 0:
                return (i, j)
    return (-1, -1)

import math

def tilingrectangle(n: int, m: int) -> int:
    grid = [[0 for _ in range(m)] for _ in range(n)]

    def try_place(i: int, j: int, l: int) -> bool:
        ok = True
        (xb, yb) = (None, None)
        for x in range(i, i + l):
            for y in range(j, j + l):
                if grid[x][y] == 1:
                    ok = False
                    (xb, yb) = (x, y)
                    break
                grid[x][y] = 1
            if not ok:
                break
        if not ok:
            done = False
            for x in range(i, i + l):
                for y in range(j, j + l):
                    if (x, y) == (xb, yb):
                        done = True
                        break
                    grid[x][y] = 0
                if done:
                    break
        return ok

    def un_place(i: int, j: int, l: int):
        for x in range(i, i + l):
            for y in range(j, j + l):
                grid[x][y] = 0

    def search(i: int, j: int, sofar: int, ans: list):
        if sofar >= ans[0]:
            return
        if j == m:
            ans[0] = min(ans[0], sofar)
            return
        if i == n:
            search(0, j + 1, sofar, ans)
            return
        if grid[i][j] == 1:
            search(i + 1, j, sofar, ans)
            return
        for l in reversed(range(1, min(n - i + 1, m - j + 1))):
            if try_place(i, j, l):
                search(i + 1, j, sofar + 1, ans)
                un_place(i, j, l)
    if len(grid) == len(grid[0]):
        return 1
    ans = [math.inf]
    search(0, 0, 0, ans)
    return ans[0]

