    return all((aj + ak <= 10 for (aj, ak) in zip(a, a[:(len(a) - 1) // 2:-1])))

def is_onion_array(a):
    for i in range(0, len(a) // 2):
        if a[i] + a[-i - 1] > 10:
            return False
    return True

def is_onion_array(a):
    for j in range(len(a) // 2):
        if a[j] + a[-j - 1] > 10:
            return False
    return True

def is_onion_array(a):
    if a == []:
        return True
    a = [sum(x) for x in zip(a, a[::-1])]
    a.pop(len(a) // 2)
    for element in a:
        if element > 10:
            return False
    return True

def is_onion_array(a):
    i = 0
    j = -1
    while i != len(a) // 2:
        if a[i] + a[j] > 10:
            return False
        i += 1
        j -= 1
    return True

