    surfix = [0 for _ in range(n_nums + 1)]
    surfix[n_nums - 1] = 1
    for i in range(n_nums - 2, -1, -1):
        accu = surfix[i + 1] - surfix[min(n_nums, i + nums[i] + 1)]
        if accu > 0:
            surfix[i] = surfix[i + 1] + 1
        else:
            surfix[i] = surfix[i + 1]
    return surfix[0] > surfix[1]

def canjump(nums):
    if not nums or len(nums) == 1:
        return True
    status = [False] * (len(nums) - 1) + [True]
    curr = len(nums) - 1
    for j in range(len(nums) - 2, -1, -1):
        if status[min(len(nums) - 1, j + nums[j])]:
            for i in range(j, curr):
                status[i] = True
            curr = j
    return status[0]

