def sumsubseqwidths(A: List[int]) -> int:
    n = len(A)
    ret = 0
    A.sort()
    ret = 0
    f = {}
    for (i, x) in enumerate(A):
        if x not in f:
            f[x] = [i, i]
        else:
            f[x][1] = i
    ret = 0
    for x in f:
        (l, r) = f[x]
        sl = l
        sr = n - r - 1
        se = r - l + 1
        ret += (2 ** sl - 1) * (2 ** se - 1) * x
        ret -= (2 ** sr - 1) * (2 ** se - 1) * x
    return ret % (10 ** 9 + 7)

def sumsubseqwidths(A: List[int]) -> int:
    N = len(A)
    if N == 1:
        return 0
    MOD = 10 ** 9 + 7
    A.sort()
    pow2 = [1]
    widths = 0
    for i in range(1, N):
        pow2.append(pow2[-1] * 2 % MOD)
    for i in range(N):
        widths = (widths + (pow2[i] - pow2[N - 1 - i]) * A[i]) % MOD
    return widths

