def search(A, i, j, visited):
    q = collections.deque()
    q.append((i, j))
    visited.append((i, j))
    while q:
        size = len(q)
        for i in range(size):
            (r, c) = q.popleft()
            dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]
            for d in dirs:
                newr = r + d[0]
                newc = c + d[1]
