def expand(A, level, length):
    for i in range(length):
        for j in range(length):
            if A[i][j] == level:
                if i > 0:
                    if A[i - 1][j] == 1:
                        return level
                    elif A[i - 1][j] == 0:
                        A[i - 1][j] = level + 1
                if j > 0:
                    if A[i][j - 1] == 1:
                        return level
                    elif A[i][j - 1] == 0:
                        A[i][j - 1] = level + 1
                if i < length - 1:
                    if A[i + 1][j] == 1:
                        return level
                    elif A[i + 1][j] == 0:
                        A[i + 1][j] = level + 1
                if j < length - 1:
                    if A[i][j + 1] == 1:
                        return level
                    elif A[i][j + 1] == 0:
                        A[i][j + 1] = level + 1
    return 0

