def find_island():
    done = set()
    islands = []
    for r in range(len(self.map)):
        for c in range(len(self.map[0])):
            if self.map[r][c] and (r, c) not in done:
                stack = [(r, c)]
                seen = {(r, c)}
                while stack:
                    cell = stack.pop(0)
                    neighbors = self.get_neighbors(cell[0], cell[1])
                    for nei in neighbors:
                        if self.map[nei[0]][nei[1]] and nei not in seen:
                            stack.append(nei)
                            seen.add(nei)
                islands.append(seen)
                done |= seen
    return islands

