def sequence_sum(a, b, step):
    n = (b - a) // step
    return 0 if n < 0 else (n + 1) * (n * step + a + a) // 2

def sequence_sum(b, e, s):
    (q, r) = divmod(e - b, s)
    return (b + e - r) * max(q + 1, 0) // 2

def sequence_sum(b, e, s):
    if s > 0 and b > e or (s < 0 and b < e):
        return 0
    near = e - (e - b) % s
    n = (near - b) // s + 1
    return (b + near) * n // 2

def sequence_sum(b, e, s):
    if b > e and s > 0 or (b < e and s < 0):
        return 0
    k = (e - b) // s
    return b * (k + 1) + s * (k * (k + 1)) // 2

def sequence_sum(begin, end, step):
    n = int((end - begin + step) / step)
    an = begin + (n - 1) * step
    if step > 0:
        if begin > end:
            return 0
    if step < 0:
        if begin < end:
            return 0
    if n % 2 == 0:
        res = int(int(n / 2) * (begin + an))
    if (begin + an) % 2 == 0:
        res = int(int((begin + an) / 2) * n)
    return res

from decimal import Decimal

def sequence_sum(s, e, step):
    if s > e and step > 0 or (s < e and step < 0):
        return 0
    elems = abs(s - e) // abs(step) + 1
    last = s + step * (elems - 1)
    avg = (s + last) / 2
    return int(Decimal(elems) * Decimal(avg))

def sequence_sum(a, b, s):
    n = (b - a) // s
    return 0 if n < 0 else (n + 1) * (2 * a + s * n) // 2

