def sortList(head):
    if not head or not head.next:
        return head
    (l1, l2) = split(head)
    l1 = sortList(l1)
    l2 = sortList(l2)
    return merge(l1, l2)

def split(l):
    fast = l
    slow = l
    while fast.next and fast.next.next:
        fast = fast.next.next
        slow = slow.next
    temp = slow.next
    slow.next = None
    return (l, temp)

def merge(l1, l2):
    if not l1:
        return l2
    if not l2:
        return l1
    if l1.data <= l2.data:
        res = l1
        l1 = l1.next
    else:
        res = l2
        l2 = l2.next
    h = res
    while l1 and l2:
        if l1.data <= l2.data:
            h.next = l1
            l1 = l1.next
        else:
            h.next = l2
            l2 = l2.next
        h = h.next
    if l1:
        h.next = l1
    if l2:
        h.next = l2
    return res

