def join_linked_list(h1, h2):
    if h1 == None and h2 == None:
        return None
    if h1 == None:
        return h2
    if h2 == None:
        return h1
    temp = None
    if h1.data < h2.data:
        temp = h1
        temp.next = union(h1.next, h2)
    elif h2.data < h1.data:
        temp = h2
