def solve(s, dp, start, end):
    if start > end:
        return 0
    if start == end:
        return 1
    if dp[start][end] != -1:
        return dp[start][end]
    op1 = op2 = op3 = 1000000000.0
    op1 = 1 + self.solve(s, dp, start + 1, end)
    if s[start] == s[start + 1]:
        op2 = 1 + self.solve(s, dp, start + 2, end)
    for i in range(start + 2, end + 1):
        if s[start] == s[i]:
            op3 = min(op3, self.solve(s, dp, start + 1, i - 1) + self.solve(s, dp, i + 1, end))
    dp[start][end] = min(op1, op2, op3)
    return dp[start][end]

