def min_steps(i, j, s, dp):
    if i > j:
        return 0
    if i == j:
        return 1
    if dp[i][j] != -1:
        return dp[i][j]
    min_steps = 1 + self.min_steps(i + 1, j, s, dp)
    if s[i] == s[i + 1]:
        min_steps = 1 + min(min_steps, self.min_steps(i + 2, j, s, dp))
    for k in range(i + 2, j + 1):
        if s[i] == s[k]:
            steps = self.min_steps(i + 1, k - 1, s, dp) + self.min_steps(k + 1, j, s, dp)
            min_steps = min(min_steps, steps)
    dp[i][j] = min_steps
    return dp[i][j]

