        for (tr, tc) in [(r, c), (c, r), (n - 1 - r, c), (n - 1 - c, r), (r, n - 1 - c), (c, n - 1 - r), (n - 1 - c, n - 1 - r), (n - 1 - r, n - 1 - c)]:
            if (tr, tc, k) in dp:
                return dp[tr, tc, k]
        res = 0
        for (nr, nc) in [(r - 2, c - 1), (r - 2, c + 1), (r - 1, c + 2), (r - 1, c - 2), (r + 1, c + 2), (r + 1, c - 2), (r + 2, c - 1), (r + 2, c + 1)]:
            res += dfs(nr, nc, k - 1)
        res /= 8
        dp[r, c, k] = res
        return res
    return dfs(r, c, k)

def find(rMax, cMax, x, y, steps, u):
    if steps == 0:
        return 1
    if u[x][y][steps] != -1:
        return u[x][y][steps]
    c = 0
    if x + 1 < rMax and y + 2 < cMax:
        c += find(rMax, cMax, x + 1, y + 2, steps - 1, u)
    if x + 1 < rMax and y - 2 >= 0:
        c += find(rMax, cMax, x + 1, y - 2, steps - 1, u)
    if x - 1 >= 0 and y + 2 < cMax:
        c += find(rMax, cMax, x - 1, y + 2, steps - 1, u)
    if x - 1 >= 0 and y - 2 >= 0:
        c += find(rMax, cMax, x - 1, y - 2, steps - 1, u)
    if x + 2 < rMax and y + 1 < cMax:
        c += find(rMax, cMax, x + 2, y + 1, steps - 1, u)
    if x + 2 < rMax and y - 1 >= 0:
        c += find(rMax, cMax, x + 2, y - 1, steps - 1, u)
    if x - 2 >= 0 and y + 1 < cMax:
        c += find(rMax, cMax, x - 2, y + 1, steps - 1, u)
    if x - 2 >= 0 and y - 1 >= 0:
        c += find(rMax, cMax, x - 2, y - 1, steps - 1, u)
    u[x][y][steps] = c
    return c

def findprob(N, start_x, start_y, steps):
    u = [[[-1 for _ in range(steps + 1)] for _ in range(N)] for _ in range(N)]
    val = find(N, N, start_x, start_y, steps, u)
